//! WP-1739: the SVE and SME ACLE builtins (`__builtin_sve_*`,
//! `__builtin_sme_*`) clang 22 and clang 19 lower, with how each one is
//! lowered (spec/landed/codegen/WP-810.md "Builtin aliases").
//!
//! The table (`sve_builtins.rs`) is generated by
//! `scripts/gen-sve-builtins.py` from the `-O0` IR clang 22 and clang 19
//! emit for one call of each builtin. A builtin's lowering is a *family*
//! (a recipe of IR operations with its types and intrinsics as slots)
//! filled with the row's types and intrinsics. The family text is
//! `;`-separated operations, each a space-separated list:
//! - `S ret params...`: the builtin's signature (`#`: an immediate);
//! - `D @k[.T...] ret params...`: declare intrinsic `k` of the row,
//!   mangled with the overload types `T`;
//! - `a k`: evaluate argument `k`;
//! - `c d values...`: call the `d`-th declared intrinsic;
//! - `ev v i`, `iv agg v i` (`i` a number or immediate `#k`), `ie vec elt
//!   i`, `sv a b mask` (a `T:Z` mask: a splat), `sel c t f`,
//!   `gep T base idx`, `zext|sext|trunc|bitcast v T`,
//!   `shl|mul|add[.nuw|.nsw] a b`, `icmp.ne a b`: the instructions;
//! - `r [v]`: the result.
//!
//! An operation's value is `%n` (the result of the `n`-th operation after
//! the `S` and `D` ones), `T:k` (a constant: an integer, `P` poison, `U`
//! undef or `Z` zeroinitializer) or `T#k[*s][+o]` (immediate argument `k`,
//! scaled and offset). A type is `$n` (the row's `n`-th type), `i32`,
//! `i64`, `p` or `void`; a row's types are abbreviated LLVM types (see
//! [`type_text`]).

use std::sync::OnceLock;

use crate::sve_builtins as t;

/// A builtin's lowering at one clang version.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Lowering {
    /// The family's operations.
    pub family: &'static str,
    /// The intrinsics, `,`-separated indexes for [`intrinsic`].
    pub intrinsics: &'static str,
    /// The types, `,`-separated indexes for [`type_text`].
    pub types: &'static str,
}

/// An intrinsic a family calls.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Intrinsic {
    /// The name without its overload suffixes (`llvm.aarch64.sve.ld1`).
    pub name: &'static str,
    /// Its function attributes for LLVM 22 then 19 (`None`: clang of that
    /// version never declares it).
    pub attrs: [Option<&'static str>; 2],
    /// Its parameters' attributes for LLVM 22 then 19, one character each:
    /// `.` none, `i` `immarg`, `c` `nocapture`.
    pub params: [&'static str; 2],
}

fn lines(s: &'static str) -> Vec<&'static str> {
    s.split('\n').collect()
}

fn rows() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::ROWS))
}

fn families() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::FAMILIES))
}

fn types() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::TYPES))
}

fn attr_sets() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::ATTRS))
}

fn bases() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::BASES))
}

/// The row of builtin `name` (`sve_svadd_s32_x`: the name without its
/// `__builtin_` prefix).
fn row(name: &str) -> Option<&'static str> {
    let rows = rows();
    let i = rows.binary_search_by(|r| r.split(' ').next().unwrap_or("").cmp(name)).ok()?;
    Some(rows[i])
}

fn lowering(spec: &'static str) -> Option<Lowering> {
    let mut it = spec.split(':');
    let f: usize = it.next()?.parse().ok()?;
    Some(Lowering { family: families().get(f)?, intrinsics: it.next()?, types: it.next()? })
}

/// How clang `version` (22 or later, else 19) lowers builtin `name`
/// (`__builtin_sve_svadd_s32_x`): `None` when that clang has no such SVE or
/// SME builtin (or kiln lacks one of its types: the FP8 ones).
pub fn lookup(name: &str, version: u32) -> Option<Lowering> {
    let r = row(name.strip_prefix("__builtin_")?)?;
    let mut it = r.split(' ').skip(1);
    let s22 = it.next()?;
    let s19 = it.next()?;
    let spec = match (version >= 22, s19) {
        (false, "-") => return None,
        (false, "=") | (true, _) => s22,
        (false, s) => s,
    };
    lowering(spec)
}

/// The number of builtins in the table, and of those clang 19 has.
pub fn counts() -> (usize, usize) {
    let r = rows();
    (r.len(), r.iter().filter(|r| !r.ends_with(" -")).count())
}

/// The abbreviated LLVM type `i`: `s<n><T>` `<vscale x n x T>`,
/// `v<n><T>` `<n x T>`, `{T,...}` a literal struct, `c`
/// `target("aarch64.svcount")`, `h` half, `bf` bfloat, `f` float, `d`
/// double, `p` ptr, `i<n>`, `void`.
pub fn type_text(i: usize) -> Option<&'static str> {
    types().get(i).copied()
}

/// Intrinsic `i` of the table.
pub fn intrinsic(i: usize) -> Option<Intrinsic> {
    let mut it = bases().get(i)?.split(' ');
    let name = it.next()?;
    let mut attrs = [None; 2];
    let mut params = [""; 2];
    for v in 0..2 {
        let a = it.next()?;
        let p = it.next()?;
        if a != "-" {
            attrs[v] = Some(*attr_sets().get(a.parse::<usize>().ok()?)?);
            params[v] = if p == "-" { "" } else { p };
        }
    }
    Some(Intrinsic { name, attrs, params })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table() {
        let (all, in19) = counts();
        assert!(all > in19 && in19 > 8000, "{all} {in19}");
        let rows = rows();
        assert!(rows.windows(2).all(|w| w[0].split(' ').next() < w[1].split(' ').next()));
        for r in rows {
            let name = format!("__builtin_{}", r.split(' ').next().unwrap_or(""));
            let l = lookup(&name, 22).unwrap_or_else(|| panic!("{r}"));
            for i in l.intrinsics.split(',').filter(|s| !s.is_empty()) {
                assert!(intrinsic(i.parse().unwrap_or(usize::MAX)).is_some(), "{r}");
            }
            for i in l.types.split(',').filter(|s| !s.is_empty()) {
                assert!(type_text(i.parse().unwrap_or(usize::MAX)).is_some(), "{r}");
            }
            assert_eq!(lookup(&name, 19).is_some(), !r.ends_with(" -"), "{r}");
        }
        assert!(lookup("__builtin_sve_svadd_s32_x", 19).is_some());
        assert!(lookup("__builtin_sve_svbogus", 22).is_none());
    }
}
